insert into sections (work_id, parent_id, level, ordinal, ref, title_iast, title_sa, status)
values ((select id from works where slug='bhagavata-purana'), null, 1, 1, '1', 'Prathama Skandha', 'प्रथमः स्कन्धः', 'published')
on conflict (work_id, ref) do update set title_iast=excluded.title_iast, title_sa=excluded.title_sa, ordinal=excluded.ordinal, status='published';
insert into sections (work_id, parent_id, level, ordinal, ref, title_iast, title_sa, summary, status, metadata)
values ((select id from works where slug='bhagavata-purana'), (select id from sections where work_id=(select id from works where slug='bhagavata-purana') and ref='1'),
        2, 1, '1.1', 'Naimiṣīyopākhyāna — Praśnāḥ (The Sages'' Questions)', 'नैमिषीयोपाख्याने ऋषिप्रश्नः', 'After three invocatory verses defining the supreme truth and the purpose of the Bhāgavata, the sages led by Śaunaka, performing a thousand-year sacrifice at Naimiṣāraṇya, honour Sūta and ask him what is the ultimate good for people in the age of Kali.', 'published',
        '{"title_iast": "Naimiṣīyopākhyāna — Praśnāḥ (The Sages'' Questions)", "title_sa": "नैमिषीयोपाख्याने ऋषिप्रश्नः", "title_en": "The Questions of the Sages at Naimiṣāraṇya", "title_ml": "നൈമിഷാരണ്യത്തിലെ ഋഷിമാരുടെ ചോദ്യങ്ങൾ", "summary_en": "After three invocatory verses defining the supreme truth and the purpose of the Bhāgavata, the sages led by Śaunaka, performing a thousand-year sacrifice at Naimiṣāraṇya, honour Sūta and ask him what is the ultimate good for people in the age of Kali.", "summary_ml": "പരമസത്യത്തെയും ഭാഗവതത്തിന്റെ ലക്ഷ്യത്തെയും നിർവചിക്കുന്ന മൂന്ന് മംഗളശ്ലോകങ്ങൾക്കു ശേഷം, നൈമിഷാരണ്യത്തിൽ ആയിരം വർഷത്തെ സത്രം അനുഷ്ഠിക്കുന്ന ശൗനകാദി ഋഷിമാർ സൂതനെ ആദരിച്ച് കലിയുഗത്തിലെ ജനങ്ങൾക്ക് പരമമായ ശ്രേയസ്സ് എന്തെന്ന് ചോദിക്കുന്നു.", "colophon_sa": "इति श्रीमद्भागवते महापुराणे पारमहंस्यां संहितायां प्रथमस्कन्धे नैमिषीयोपाख्याने प्रथमोऽध्यायः ॥ १ ॥"}'::jsonb)
on conflict (work_id, ref) do update set title_iast=excluded.title_iast, title_sa=excluded.title_sa, summary=excluded.summary, ordinal=excluded.ordinal, parent_id=excluded.parent_id, status='published', metadata=excluded.metadata;
insert into section_contents (section_id, edition_id, title, summary, status)
values ((select id from sections where ref='1.1' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-en-dl'), 'The Questions of the Sages at Naimiṣāraṇya', 'After three invocatory verses defining the supreme truth and the purpose of the Bhāgavata, the sages led by Śaunaka, performing a thousand-year sacrifice at Naimiṣāraṇya, honour Sūta and ask him what is the ultimate good for people in the age of Kali.', 'published')
on conflict (section_id, edition_id) do update set title=excluded.title, summary=excluded.summary, status='published';
insert into section_contents (section_id, edition_id, title, summary, status)
values ((select id from sections where ref='1.1' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-ml-dl'), 'നൈമിഷാരണ്യത്തിലെ ഋഷിമാരുടെ ചോദ്യങ്ങൾ', 'പരമസത്യത്തെയും ഭാഗവതത്തിന്റെ ലക്ഷ്യത്തെയും നിർവചിക്കുന്ന മൂന്ന് മംഗളശ്ലോകങ്ങൾക്കു ശേഷം, നൈമിഷാരണ്യത്തിൽ ആയിരം വർഷത്തെ സത്രം അനുഷ്ഠിക്കുന്ന ശൗനകാദി ഋഷിമാർ സൂതനെ ആദരിച്ച് കലിയുഗത്തിലെ ജനങ്ങൾക്ക് പരമമായ ശ്രേയസ്സ് എന്തെന്ന് ചോദിക്കുന്നു.', 'published')
on conflict (section_id, edition_id) do update set title=excluded.title, summary=excluded.summary, status='published';
insert into verses (work_id, section_id, ordinal, ref, kind, meter, speaker_id, status)
values ((select id from works where slug='bhagavata-purana'), (select id from sections where ref='1.1' and work_id=(select id from works where slug='bhagavata-purana')),
        1, '1.1.1', 'invocation'::verse_kind, 'śārdūlavikrīḍita', (select id from people where slug=null), 'published')
on conflict (work_id, ref) do update set ordinal=excluded.ordinal, kind=excluded.kind, meter=excluded.meter, speaker_id=excluded.speaker_id, section_id=excluded.section_id, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.1' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-mula-deva'),
        'ॐ नमो भगवते वासुदेवाय ।
जन्माद्यस्य यतोऽन्वयादितरतश्चार्थेष्वभिज्ञः स्वराट्
तेने ब्रह्म हृदा य आदिकवये मुह्यन्ति यत्सूरयः ।
तेजोवारिमृदां यथा विनिमयो यत्र त्रिसर्गोऽमृषा
धाम्ना स्वेन सदा निरस्तकुहकं सत्यं परं धीमहि ॥ १ ॥', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.1' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-iast'),
        'oṁ namo bhagavate vāsudevāya
janmādy asya yato ''nvayād itarataś cārtheṣv abhijñaḥ svarāṭ
tene brahma hṛdā ya ādi-kavaye muhyanti yat sūrayaḥ
tejo-vāri-mṛdāṁ yathā vinimayo yatra tri-sargo ''mṛṣā
dhāmnā svena sadā nirasta-kuhakaṁ satyaṁ paraṁ dhīmahi', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.1' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-en-dl'),
        'Oṁ. Obeisance to the blessed Lord Vāsudeva.
We meditate upon the supreme truth — that from whom this universe has its birth, sustenance and dissolution; who is present in all things and yet distinct from them; who is fully aware of every object and independent; who imparted the Veda into the heart of the first seer, Brahmā, and about whom even the wise are bewildered; in whom the threefold creation appears real, just as fire, water and earth are mistaken for one another; and who by his own radiance forever dispels all illusion.', null, 'The opening verse echoes the Gāyatrī (dhīmahi) and the Vedānta-sūtra 1.1.2 (janmādy asya yataḥ). The maṅgala ''oṁ namo bhagavate vāsudevāya'' precedes the verse in the printed vulgate.', 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.1' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-ml-dl'),
        'ഓം. ഭഗവാൻ വാസുദേവന് നമസ്കാരം.
ഈ പ്രപഞ്ചത്തിന്റെ സൃഷ്ടിയും സ്ഥിതിയും ലയവും ആരിൽനിന്നാണോ; സകലതിലും അന്വയിച്ചിരിക്കുകയും അതേസമയം അവയിൽനിന്ന് വ്യതിരിക്തനുമായ; സർവാർത്ഥങ്ങളെയും അറിയുന്നവനും സ്വതന്ത്രനുമായ; ആദികവിയായ ബ്രഹ്മാവിന്റെ ഹൃദയത്തിൽ വേദത്തെ പകർന്നവനും, ആരെക്കുറിച്ച് പണ്ഡിതന്മാർ പോലും മോഹിക്കുന്നുവോ; തേജസ്സ്, ജലം, മണ്ണ് എന്നിവ പരസ്പരം തെറ്റിദ്ധരിക്കപ്പെടുന്നതുപോലെ ആരിൽ ത്രിവിധസൃഷ്ടി സത്യമെന്നു തോന്നുന്നുവോ; സ്വന്തം തേജസ്സുകൊണ്ട് സദാ സകലമായയെയും അകറ്റുന്നവനുമായ ആ പരമസത്യത്തെ ഞങ്ങൾ ധ്യാനിക്കുന്നു.', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.1' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-mula-mlym'),
        'ഓം നമോ ഭഗവതേ വാസുദേവായ ।
ജന്മാദ്യസ്യ യതോഽന്വയാദിതരതശ്ചാർഥേഷ്വഭിജ്ഞഃ സ്വരാട്
തേനേ ബ്രഹ്മ ഹൃദാ യ ആദികവയേ മുഹ്യന്തി യത്സൂരയഃ ।
തേജോവാരിമൃദാം യഥാ വിനിമയോ യത്ര ത്രിസർഗോഽമൃഷാ
ധാമ്നാ സ്വേന സദാ നിരസ്തകുഹകം സത്യം പരം ധീമഹി ॥ ൧ ॥', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.1' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-mula-knda'),
        'ಓಂ ನಮೋ ಭಗವತೇ ವಾಸುದೇವಾಯ ।
ಜನ್ಮಾದ್ಯಸ್ಯ ಯತೋಽನ್ವಯಾದಿತರತಶ್ಚಾರ್ಥೇಷ್ವಭಿಜ್ಞಃ ಸ್ವರಾಟ್
ತೇನೇ ಬ್ರಹ್ಮ ಹೃದಾ ಯ ಆದಿಕವಯೇ ಮುಹ್ಯನ್ತಿ ಯತ್ಸೂರಯಃ ।
ತೇಜೋವಾರಿಮೃದಾಂ ಯಥಾ ವಿನಿಮಯೋ ಯತ್ರ ತ್ರಿಸರ್ಗೋಽಮೃಷಾ
ಧಾಮ್ನಾ ಸ್ವೇನ ಸದಾ ನಿರಸ್ತಕುಹಕಂ ಸತ್ಯಂ ಪರಂ ಧೀಮಹಿ ॥ ೧ ॥', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.1' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-mula-telu'),
        'ఓం నమో భగవతే వాసుదేవాయ ।
జన్మాద్యస్య యతోఽన్వయాదితరతశ్చార్థేష్వభిజ్ఞః స్వరాట్
తేనే బ్రహ్మ హృదా య ఆదికవయే ముహ్యన్తి యత్సూరయః ।
తేజోవారిమృదాం యథా వినిమయో యత్ర త్రిసర్గోఽమృషా
ధామ్నా స్వేన సదా నిరస్తకుహకం సత్యం పరం ధీమహి ॥ ౧ ॥', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.1' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-mula-beng'),
        'ওঁ নমো ভগবতে বাসুদেবায ।
জন্মাদ্যস্য যতোঽন্বযাদিতরতশ্চার্থেষ্বভিজ্ঞঃ স্বরাট্
তেনে ব্রহ্ম হৃদা য আদিকবযে মুহ্যন্তি যত্সূরযঃ ।
তেজোবারিমৃদাং যথা বিনিমযো যত্র ত্রিসর্গোঽমৃষা
ধাম্না স্বেন সদা নিরস্তকুহকং সত্যং পরং ধীমহি ॥ ১ ॥', null, null, 'published')
