insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.1' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-mula-gujr'),
        'ૐ નમો ભગવતે વાસુદેવાય ।
જન્માદ્યસ્ય યતોઽન્વયાદિતરતશ્ચાર્થેષ્વભિજ્ઞઃ સ્વરાટ્
તેને બ્રહ્મ હૃદા ય આદિકવયે મુહ્યન્તિ યત્સૂરયઃ ।
તેજોવારિમૃદાં યથા વિનિમયો યત્ર ત્રિસર્ગોઽમૃષા
ધામ્ના સ્વેન સદા નિરસ્તકુહકં સત્યં પરં ધીમહિ ॥ ૧ ॥', null, null, 'published')
