insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.2' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-mula-deva'),
        'धर्मः प्रोज्झितकैतवोऽत्र परमो निर्मत्सराणां सतां
वेद्यं वास्तवमत्र वस्तु शिवदं तापत्रयोन्मूलनम् ।
श्रीमद्भागवते महामुनिकृते किं वा परैरीश्वरः
सद्यो हृद्यवरुध्यतेऽत्र कृतिभिः शुश्रूषुभिस्तत्क्षणात् ॥ २ ॥', null, null, 'published')
