values ((select id from verses where ref='1.1.2' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-iast'),
        'dharmaḥ projjhita-kaitavo ''tra paramo nirmatsarāṇāṁ satāṁ
vedyaṁ vāstavam atra vastu śivadaṁ tāpa-trayonmūlanam
śrīmad-bhāgavate mahā-muni-kṛte kiṁ vā parair īśvaraḥ
sadyo hṛdy avarudhyate ''tra kṛtibhiḥ śuśrūṣubhis tat-kṣaṇāt', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.2' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-en-dl'),
        'Here is set forth the highest dharma, free of every ulterior motive, for the good who are without envy; here the real substance is to be known — that which grants well-being and uproots the threefold misery. In this Śrīmad Bhāgavata, composed by the great sage, what need is there of any other scripture? The Lord is at once captured in the heart of those who are fortunate enough to wish to hear it — in that very moment.', null, 'tāpa-traya: the three miseries — ādhyātmika (from one''s own body and mind), ādhibhautika (from other beings), ādhidaivika (from natural forces).', 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.2' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-ml-dl'),
        'അസൂയയില്ലാത്ത സജ്ജനങ്ങൾക്കായി, സകലകപടവും വെടിഞ്ഞ പരമധർമ്മം ഇവിടെ പ്രതിപാദിക്കപ്പെടുന്നു; ത്രിതാപങ്ങളെ വേരോടെ പിഴുതെറിയുന്ന, മംഗളം നൽകുന്ന യഥാർത്ഥവസ്തുവാണ് ഇവിടെ അറിയേണ്ടത്. മഹാമുനി രചിച്ച ഈ ശ്രീമദ്ഭാഗവതം ഉള്ളപ്പോൾ മറ്റു ശാസ്ത്രങ്ങൾകൊണ്ട് എന്തു കാര്യം? ഇത് കേൾക്കാൻ ആഗ്രഹിക്കുന്ന പുണ്യവാന്മാരുടെ ഹൃദയത്തിൽ ഈശ്വരൻ ആ ക്ഷണത്തിൽത്തന്നെ ബന്ധിക്കപ്പെടുന്നു.', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.2' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-mula-mlym'),
        'ധർമഃ പ്രോജ്ഝിതകൈതവോഽത്ര പരമോ നിർമത്സരാണാം സതാം
വേദ്യം വാസ്തവമത്ര വസ്തു ശിവദം താപത്രയോന്മൂലനമ് ।
ശ്രീമദ്ഭാഗവതേ മഹാമുനികൃതേ കിം വാ പരൈരീശ്വരഃ
സദ്യോ ഹൃദ്യവരുധ്യതേഽത്ര കൃതിഭിഃ ശുശ്രൂഷുഭിസ്തത്ക്ഷണാത് ॥ ൨ ॥', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.2' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-mula-knda'),
        'ಧರ್ಮಃ ಪ್ರೋಜ್ಝಿತಕೈತವೋಽತ್ರ ಪರಮೋ ನಿರ್ಮತ್ಸರಾಣಾಂ ಸತಾಂ
ವೇದ್ಯಂ ವಾಸ್ತವಮತ್ರ ವಸ್ತು ಶಿವದಂ ತಾಪತ್ರಯೋನ್ಮೂಲನಮ್ ।
ಶ್ರೀಮದ್ಭಾಗವತೇ ಮಹಾಮುನಿಕೃತೇ ಕಿಂ ವಾ ಪರೈರೀಶ್ವರಃ
ಸದ್ಯೋ ಹೃದ್ಯವರುಧ್ಯತೇಽತ್ರ ಕೃತಿಭಿಃ ಶುಶ್ರೂಷುಭಿಸ್ತತ್ಕ್ಷಣಾತ್ ॥ ೨ ॥', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.2' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-mula-telu'),
        'ధర్మః ప్రోజ్ఝితకైతవోఽత్ర పరమో నిర్మత్సరాణాం సతాం
వేద్యం వాస్తవమత్ర వస్తు శివదం తాపత్రయోన్మూలనమ్ ।
శ్రీమద్భాగవతే మహామునికృతే కిం వా పరైరీశ్వరః
సద్యో హృద్యవరుధ్యతేఽత్ర కృతిభిః శుశ్రూషుభిస్తత్క్షణాత్ ॥ ౨ ॥', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.2' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-mula-beng'),
        'ধর্মঃ প্রোজ্ঝিতকৈতবোঽত্র পরমো নির্মত্সরাণাং সতাং
বেদ্যং বাস্তবমত্র বস্তু শিবদং তাপত্রযোন্মূলনম্ ।
শ্রীমদ্ভাগবতে মহামুনিকৃতে কিং বা পরৈরীশ্বরঃ
সদ্যো হৃদ্যবরুধ্যতেঽত্র কৃতিভিঃ শুশ্রূষুভিস্তত্ক্ষণাত্ ॥ ২ ॥', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.2' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-mula-gujr'),
        'ધર્મઃ પ્રોજ્ઝિતકૈતવોઽત્ર પરમો નિર્મત્સરાણાં સતાં
વેદ્યં વાસ્તવમત્ર વસ્તુ શિવદં તાપત્રયોન્મૂલનમ્ ।
શ્રીમદ્ભાગવતે મહામુનિકૃતે કિં વા પરૈરીશ્વરઃ
સદ્યો હૃદ્યવરુધ્યતેઽત્ર કૃતિભિઃ શુશ્રૂષુભિસ્તત્ક્ષણાત્ ॥ ૨ ॥', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='1.1.2' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-wm-en'),
        'dharmaḥ — dharma, religion
projjhita-kaitavaḥ — from which all deceit / ulterior motive is cast out
atra — here (in this work)
paramaḥ — the highest
nirmatsarāṇām satām — of the good who are free from envy
vedyam — to be known
vāstavam vastu — the real substance / reality
śiva-dam — bestowing well-being
tāpa-traya-unmūlanam — uprooting the three miseries
śrīmad-bhāgavate — in the Śrīmad Bhāgavata
mahā-muni-kṛte — composed by the great sage (Vyāsa)
kim vā paraiḥ — what use of others?
īśvaraḥ — the Lord
sadyaḥ — at once
hṛdi avarudhyate — is confined / captured in the heart
kṛtibhiḥ — by the fortunate, the accomplished
śuśrūṣubhiḥ — by those desiring to hear
