values ((select id from verses where ref='1.1.3' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-en-dl'),
        'O connoisseurs of taste, O sensitive souls upon the earth! Drink again and again this Bhāgavata — the ripe fruit fallen from the wish-fulfilling tree of the Veda, made yet sweeter with nectar from the mouth of Śuka — this rasa, this very abode of relish.', null, 'A double meaning is traditionally read in śuka-mukhāt: a fruit touched by a parrot''s (śuka) beak is sweeter, and the Bhāgavata comes from the mouth of Śuka, son of Vyāsa.', 'published')
