values ((select id from verses where ref='1.1.3' and work_id=(select id from works where slug='bhagavata-purana')), (select id from editions where slug='sb-ml-dl'),
        'അല്ലയോ ഭൂമിയിലെ രസികന്മാരേ, ഭാവുകന്മാരേ! വേദമാകുന്ന കൽപവൃക്ഷത്തിൽനിന്ന് പഴുത്തുവീണ, ശുകന്റെ മുഖത്തുനിന്നുള്ള അമൃതരസത്താൽ കൂടുതൽ മധുരമായ ഈ ഭാഗവതമാകുന്ന രസം — രസത്തിന്റെ ഇരിപ്പിടം തന്നെയായ ഇത് — വീണ്ടും വീണ്ടും പാനം ചെയ്യുവിൻ.', null, null, 'published')
