insert into cross_references (from_verse_id, to_verse_id, kind, note, status)
select f.id, t.id, 'see_also'::xref_kind, 'The three designations of the one truth: Brahman, Paramātmā, Bhagavān.', 'published'
  from verses f, verses t
 where f.work_id=(select id from works where slug='bhagavata-purana') and f.ref='1.1.1'
   and t.work_id = f.work_id and t.ref='1.2.11'
on conflict (from_verse_id, to_verse_id, kind) do update set note=excluded.note, status='published';
update verses set metadata = jsonb_set(coalesce(metadata,'{}'::jsonb), '{pending_xrefs}',
  coalesce(metadata->'pending_xrefs','[]'::jsonb) || '{"to": "1.2.11", "kind": "see_also", "note": "The three designations of the one truth: Brahman, Paramātmā, Bhagavān."}'::jsonb)
 where work_id=(select id from works where slug='bhagavata-purana') and ref='1.1.1'
   and not exists (select 1 from verses t where t.work_id = verses.work_id and t.ref = '1.2.11')
   and not (coalesce(metadata->'pending_xrefs','[]'::jsonb) @> '[{"to": "1.2.11"}]'::jsonb);
